import React, { useState, useEffect } from 'react';
import type { ImageObject } from '../types';
import { ControlSlider, ControlSelect, SectionHeader } from './controls/CommonControls';
import { imageTracer, blur, getSvgString } from '../imagetracer';
import { OPTION_PRESETS } from '../imagetracer/presets';
import { GoogleGenAI } from "@google/genai";

interface TraceImageModalProps {
    isOpen: boolean;
    onClose: () => void;
    imageObject: ImageObject;
    onApply: (tracedata: any) => void;
}

/**
 * Modal for converting a raster image to vector paths using ImageTracer.js.
 * Provides controls for tracing parameters, live preview, and AI image enhancement.
 */
const TraceImageModal: React.FC<TraceImageModalProps> = ({ isOpen, onClose, imageObject, onApply }) => {
    const [params, setParams] = useState({
        ...OPTION_PRESETS.default,
        pathOmit: OPTION_PRESETS.default.pathomit,
    });
    const [preset, setPreset] = useState<keyof typeof OPTION_PRESETS>('default');
    const [previewSvg, setPreviewSvg] = useState<string | null>(null);
    const [tracedata, setTracedata] = useState<any | null>(null);
    const [isProcessing, setIsProcessing] = useState(false);

    // AI State
    const [activeTab, setActiveTab] = useState<'trace' | 'ai'>('trace');
    const [currentImageSrc, setCurrentImageSrc] = useState(imageObject.href);
    const [aiPrompt, setAiPrompt] = useState("");
    const [isAiLoading, setIsAiLoading] = useState(false);

    useEffect(() => {
        if (isOpen) {
            setCurrentImageSrc(imageObject.href);
            setAiPrompt("");
            setActiveTab('trace');
        }
    }, [isOpen, imageObject]);

    const handlePresetChange = (newPresetKey: string) => {
        const newPreset = newPresetKey as keyof typeof OPTION_PRESETS;
        setPreset(newPreset);

        const presetOptions = { ...OPTION_PRESETS.default, ...OPTION_PRESETS[newPreset] };

        setParams({
            ...presetOptions,
            pathOmit: presetOptions.pathomit,
        });
    };

    useEffect(() => {
        if (!isOpen) return;

        setIsProcessing(true);
        setPreviewSvg(null);
        setTracedata(null);

        const img = new Image();
        img.crossOrigin = 'Anonymous';

        img.onload = () => {
            try {
                const canvas = document.createElement('canvas');
                canvas.width = img.width;
                canvas.height = img.height;
                const ctx = canvas.getContext('2d');
                if (!ctx) {
                    console.error("Could not get canvas context for tracing.");
                    setIsProcessing(false);
                    return;
                }

                ctx.drawImage(img, 0, 0);
                const originalImageData = ctx.getImageData(0, 0, img.width, img.height);

                const presetBaseOptions = { ...OPTION_PRESETS.default, ...OPTION_PRESETS[preset] };
                let imageDataToProcess = originalImageData;

                if (params.blurradius > 0) {
                    imageDataToProcess = blur(originalImageData, params.blurradius, presetBaseOptions.blurdelta);
                }

                const options = {
                    ...presetBaseOptions,
                    ...params,
                    pathomit: params.pathOmit,
                };

                const td = imageTracer.imageDataToTracedata(imageDataToProcess, options);
                setTracedata(td);

                const svgString = getSvgString(td, { ...options, scale: 1, viewbox: true });
                const parser = new DOMParser();
                const svgDoc = parser.parseFromString(svgString, "image/svg+xml");
                const svgContent = Array.from(svgDoc.documentElement.children).map(child => child.outerHTML).join('');
                setPreviewSvg(svgContent);

            } catch (error) {
                console.error('ImageTracer error:', error);
                setPreviewSvg(null);
                setTracedata(null);
            } finally {
                setIsProcessing(false);
            }
        };

        img.onerror = () => {
            console.error("Failed to load image for tracing.");
            setIsProcessing(false);
        };

        img.src = currentImageSrc;

    }, [isOpen, currentImageSrc, params, preset]);

    const handleAiGenerate = async () => {
        if (!process.env.API_KEY) {
            alert("API Key is missing in environment variables.");
            return;
        }
        setIsAiLoading(true);
        try {
            const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

            // Helper to get base64
            const getBase64 = async (url: string): Promise<{data: string, mimeType: string}> => {
                // If it's already a data URL
                if (url.startsWith('data:')) {
                    const matches = url.match(/^data:(.+);base64,(.+)$/);
                    if (matches && matches.length === 3) {
                        return { mimeType: matches[1], data: matches[2] };
                    }
                }

                // Otherwise fetch it (blob url or external url)
                const response = await fetch(url);
                const blob = await response.blob();
                return new Promise((resolve, reject) => {
                    const reader = new FileReader();
                    reader.onloadend = () => {
                        const result = reader.result as string;
                        const base64data = result.split(',')[1];
                        resolve({ data: base64data, mimeType: blob.type });
                    };
                    reader.onerror = reject;
                    reader.readAsDataURL(blob);
                });
            };

            const { data, mimeType } = await getBase64(currentImageSrc);

            const response = await ai.models.generateContent({
                model: 'gemini-2.5-flash-image',
                contents: {
                    parts: [
                        { inlineData: { mimeType, data } },
                        { text: aiPrompt || "Enhance this image for vector tracing. High contrast, clear edges, remove noise." }
                    ]
                }
            });

            let newImageData = null;
            if (response.candidates?.[0]?.content?.parts) {
                for (const part of response.candidates[0].content.parts) {
                    if (part.inlineData) {
                        newImageData = part.inlineData.data;
                        break;
                    }
                }
            }

            if (newImageData) {
                setCurrentImageSrc(`data:image/png;base64,${newImageData}`);
                setActiveTab('trace'); // Switch back to preview the result
            } else {
                alert("AI generation did not return an image.");
            }

        } catch (e) {
            console.error("AI Generation Failed:", e);
            alert("AI Generation failed. Please try again.");
        } finally {
            setIsAiLoading(false);
        }
    };

    const handleResetImage = () => {
        setCurrentImageSrc(imageObject.href);
    };

    if (!isOpen) return null;

    const handleApply = () => {
        if (tracedata) {
            onApply(tracedata);
            onClose();
        }
    };

    return (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/60 backdrop-blur-sm" onClick={onClose}>
            <div className="bg-gray-800 border border-gray-700 rounded-xl shadow-2xl w-full max-w-4xl h-[80vh] flex flex-col" onClick={e => e.stopPropagation()}>
                <header className="flex items-center justify-between p-4 border-b border-gray-700">
                    <h2 className="text-xl font-bold">Trace Image</h2>
                    <button onClick={onClose} className="text-gray-400 hover:text-white transition-colors text-2xl">&times;</button>
                </header>

                <main className="p-6 flex-grow flex gap-6 overflow-hidden">
                    {/* Preview Area */}
                    <div className="w-2/3 flex flex-col gap-2">
                        <div className="flex-grow bg-gray-900/50 rounded-lg p-4 border border-gray-700 bg-checkered flex items-center justify-center overflow-hidden relative">
                            {isProcessing && <div className="absolute inset-0 flex items-center justify-center bg-black/50 z-10"><span className="text-white font-medium">Processing...</span></div>}

                            {!isProcessing && previewSvg && tracedata ? (
                               <div className="w-full h-full" dangerouslySetInnerHTML={{ __html: `<svg class="w-full h-full" viewBox="0 0 ${tracedata.width} ${tracedata.height}" preserveAspectRatio="xMidYMid meet">${previewSvg}</svg>` }} />
                            ) : (
                                !isProcessing && (
                                    <div className="text-gray-500 text-center">
                                        <p>No preview available.</p>
                                    </div>
                                )
                            )}
                        </div>
                        {currentImageSrc !== imageObject.href && (
                            <div className="flex justify-between items-center text-xs text-gray-400 px-1">
                                <span>Image modified by AI</span>
                                <button onClick={handleResetImage} className="text-red-400 hover:text-red-300 underline">Reset to Original</button>
                            </div>
                        )}
                    </div>

                    {/* Sidebar Controls */}
                    <div className="w-1/3 flex flex-col gap-4 overflow-y-auto custom-scrollbar pr-2">

                        {/* Tab Switcher */}
                        <div className="flex bg-gray-900 rounded-lg p-1">
                            <button onClick={() => setActiveTab('trace')} className={`flex-1 py-2 text-xs font-medium rounded-md transition-colors ${activeTab === 'trace' ? 'bg-cyan-600 text-white' : 'text-gray-400 hover:text-white'}`}>Trace Settings</button>
                            <button onClick={() => setActiveTab('ai')} className={`flex-1 py-2 text-xs font-medium rounded-md transition-colors ${activeTab === 'ai' ? 'bg-purple-600 text-white' : 'text-gray-400 hover:text-white'}`}>AI Edit</button>
                        </div>

                        {activeTab === 'trace' ? (
                            <div className="space-y-4">
                                <ControlSelect
                                    label="Preset"
                                    value={preset}
                                    onChange={handlePresetChange}
                                >
                                    {Object.keys(OPTION_PRESETS).map(p => (
                                        <option key={p} value={p}>
                                            {p.charAt(0).toUpperCase() + p.slice(1)}
                                        </option>
                                    ))}
                                </ControlSelect>

                                <div className="space-y-3">
                                    <ControlSlider label="Colors" value={params.numberofcolors} min={2} max={64} step={1} onChange={(val) => setParams(p => ({ ...p, numberofcolors: val }))} />
                                    <ControlSlider label="Blur" value={params.blurradius} min={0} max={20} step={1} onChange={(val) => setParams(p => ({ ...p, blurradius: val }))} />
                                    <ControlSlider label="Line Threshold" value={params.ltres} min={0.1} max={10} step={0.1} onChange={(val) => setParams(p => ({ ...p, ltres: val }))} />
                                    <ControlSlider label="Curve Threshold" value={params.qtres} min={0.1} max={10} step={0.1} onChange={(val) => setParams(p => ({ ...p, qtres: val }))} />
                                    <ControlSlider label="Filter Speckles" value={params.pathOmit} min={0} max={64} step={1} onChange={(val) => setParams(p => ({ ...p, pathOmit: val }))} />

                                    <div className="flex items-center justify-between pt-2">
                                        <label htmlFor="rightangle-enhance" className="text-xs font-medium text-gray-400 select-none">Enhance Right Angles</label>
                                        <button 
                                            id="rightangle-enhance"
                                            onClick={() => setParams(p => ({...p, rightangleenhance: !p.rightangleenhance}))} 
                                            className={`${params.rightangleenhance ? 'bg-cyan-600' : 'bg-gray-600'} relative inline-flex items-center h-5 rounded-full w-9 transition-colors`}
                                        >
                                            <span className={`${params.rightangleenhance ? 'translate-x-4' : 'translate-x-1'} inline-block w-3 h-3 transform bg-white rounded-full transition-transform`} />
                                        </button>
                                    </div>
                                </div>
                            </div>
                        ) : (
                            <div className="space-y-4">
                                <div className="space-y-2">
                                    <label className="block text-xs font-medium text-gray-300">Prompt</label>
                                    <textarea 
                                        value={aiPrompt}
                                        onChange={(e) => setAiPrompt(e.target.value)}
                                        placeholder="e.g. Convert to black and white line art, remove background, simplify details..."
                                        className="w-full h-32 bg-gray-900 border border-gray-700 rounded-lg p-3 text-sm text-white focus:ring-2 focus:ring-purple-500 focus:outline-none resize-none"
                                    />
                                </div>
                                <button 
                                    onClick={handleAiGenerate}
                                    disabled={isAiLoading}
                                    className="w-full bg-purple-600 hover:bg-purple-500 text-white font-bold py-2 px-4 rounded-lg transition-colors disabled:opacity-50 disabled:cursor-wait flex items-center justify-center gap-2"
                                >
                                    {isAiLoading ? (
                                        <><span>Processing...</span></>
                                    ) : (
                                        <><span>Generate with Gemini</span></>
                                    )}
                                </button>
                                <p className="text-xs text-gray-500">
                                    Uses <strong>Gemini 2.5 Flash Image</strong> to process the source image. The result will replace the current image for tracing.
                                </p>
                            </div>
                        )}
                    </div>
                </main>

                <footer className="flex justify-end p-4 bg-gray-900/50 border-t border-gray-700 space-x-3">
                    <button onClick={onClose} className="px-4 py-2 rounded-lg bg-gray-600 hover:bg-gray-500 text-white font-semibold transition-colors">Cancel</button>
                    <button onClick={handleApply} disabled={!previewSvg || isProcessing || isAiLoading} className="px-6 py-2 rounded-lg bg-cyan-600 hover:bg-cyan-500 text-white font-semibold transition-colors disabled:opacity-50 disabled:cursor-not-allowed">
                        Apply Trace
                    </button>
                </footer>
            </div>
        </div>
    );
};

export default TraceImageModal;
